ef.current = true; loadFiles(projectId); setPreviewVersion((v) => v + 1); } return; } // The dedup guard. Replay-then-follow delivers at least once; // the seq in the SSE id field makes it exactly-once where it // matters. (caughtup is handled above the guard: it carries no // id, so e.lastEventId would hold the PREVIOUS event's seq.) const seq = Number(e.lastEventId); if (seq) { if (seq { const next: ChatMessage[] = [...all]; if (event.message !== undefined) next.push({ role: "user", text: event.message }); next.push({ role: "assistant", blocks: [], status: "working", turnId: event.turnid, startedAtMs: event.startedatms ?? Date.now(), }); return next; }); Every load-bearing scrap of UI state is now computed from the log. working is not "am I holding a stream open"; it's "did I see a sessionstart without its receipt yet," so a refreshed tab and a second tab conclude "a build is running" as easily as the sender. The Stop button renders wherever working is true; the approval-waiting chip derives from an unresolved card in the blocks; and the working timer starts from startedatms, the wire timestamp, not Date.now(), so after a mid-build refresh it reads the turn's true age. Small thing; it's the difference between "the app recovered" and "the app never noticed," and users can feel which one they're using. Opening a project completes the deletion story. Part 5 gave the UI a history endpoint (thread/read, the engine's cold archive), Part 8 a usage endpoint; selecting a project called both, then started watching. All of that is gone from the open path: filename="frontend/app/page.tsx" repo="part-09-durable-streams/frontend/app/page.tsx" lines="395-406,411-412" const selectProject = useCallback( (id: string) => { setActiveId(id); setMessages([]); setBadges({}); setDiff(""); setDiffOpen(false); setFiles([]); setUsage(null); setWorking(false); setPreviewVersion((v) => v + 1); loadFiles(id); followStream(id); }, Reset, follow the stream, done. The replay is the history, and a